// ============================================================================
// INTERNAL STATE
// ============================================================================

static TaskSwitcherConfig g_config = TASK_SWITCHER_DEFAULT_CONFIG;
static TaskSwitcherState g_state = TASK_STATE_NORMAL;
static TaskSwitcherError g_last_error = TASK_ERROR_NONE;

// Parent task information (frozen task)
static TaskInfo g_parent_task = {0};

// Current task information
static TaskInfo g_current_task = {0};

// Track if we're in a switched task
static bool g_is_switched = false;

// ============================================================================
// ERROR MESSAGES
// ============================================================================

static const char* ERROR_MESSAGES[] = {
    "No error",
    "SD card not available",
    "Failed to freeze current task RAM",
    "Failed to load new task kernel",
    "Failed to restore parent task RAM",
    "No frozen task to restore",
    "Insufficient free RAM for task switch"
};

// ============================================================================
// INITIALIZATION
// ============================================================================

void task_switcher_init(void) {
    task_switcher_init_with_config(&TASK_SWITCHER_DEFAULT_CONFIG);
}

void task_switcher_init_with_config(const TaskSwitcherConfig* config) {
    if (config) {
        g_config = *config;
    }
    
    g_state = TASK_STATE_NORMAL;
    g_last_error = TASK_ERROR_NONE;
    g_is_switched = false;
    
    memset(&g_parent_task, 0, sizeof(g_parent_task));
    memset(&g_current_task, 0, sizeof(g_current_task));
    
    // Initialize current task info
    strncpy(g_current_task.kernel_path, "main", sizeof(g_current_task.kernel_path));
    g_current_task.valid = true;
    
    // Initialize SD wrapper if not already done
    sd_freeze_init();
}

TaskSwitcherState task_switcher_get_state(void) {
    return g_state;
}

TaskSwitcherError task_switcher_get_error(void) {
    return g_last_error;
}

const char* task_switcher_error_to_string(TaskSwitcherError error) {
    if (error < sizeof(ERROR_MESSAGES) / sizeof(ERROR_MESSAGES[0])) {
        return ERROR_MESSAGES[error];
    }
    return "Unknown error";
}

