// Mock function - in real implementation, use platform-specific RAM functions
static uint32_t get_total_ram(void) {
    // For ESP8266: ~80KB, ESP32: ~320KB
    // This is a placeholder - actual implementation depends on hardware
    #ifdef ESP8266
        return 80 * 1024;  // 80KB
    #elif defined(ESP32)
        return 320 * 1024;  // 320KB
    #else
        return 256 * 1024;  // Default 256KB
    #endif
}

// Mock function - in real implementation, use platform-specific RAM functions
static uint32_t get_free_ram(void) {
    // Placeholder - actual implementation uses heap/functions
    // For demo purposes, return a reasonable value
    uint32_t total = get_total_ram();
    // Assume 50% free by default for demo
    return total / 2;
}

uint8_t task_switcher_get_free_ram_percent(void) {
    uint32_t total = get_total_ram();
    if (total == 0) return 0;
    
    uint32_t free = get_free_ram();
    return (uint8_t)((free * 100) / total);
}

bool task_switcher_has_enough_ram(uint8_t required_percent) {
    uint8_t free_percent = task_switcher_get_free_ram_percent();
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Free RAM: %u%%, Required: %u%%\n", 
               free_percent, required_percent);
    }
    return free_percent >= required_percent;
}

