// ============================================================================
// TASK COMMUNICATION
// ============================================================================

bool task_save_for_parent(const char* filename, const void* data, uint32_t size) {
    if (!filename || !data || size == 0) {
        g_last_error = TASK_ERROR_LOAD_FAILED;
        return false;
    }
    
    if (!sd_card_available()) {
        g_last_error = TASK_ERROR_NO_SDCARD;
        return false;
    }
    
    char full_path[128];
    snprintf(full_path, sizeof(full_path), "%s%s", TASK_COMM_DIR, filename);
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Saving %u bytes to %s for parent\n", size, full_path);
    }
    
    // In real code: ensure directory exists, then write file
    bool result = sd_write_file(full_path, data, size);
    if (!result) {
        g_last_error = TASK_ERROR_LOAD_FAILED;
    }
    return result;
}

uint32_t task_load_from_child(const char* filename, void* buffer, uint32_t buffer_size) {
    if (!filename || !buffer || buffer_size == 0) {
        g_last_error = TASK_ERROR_LOAD_FAILED;
        return 0;
    }
    
    if (!sd_card_available()) {
        g_last_error = TASK_ERROR_NO_SDCARD;
        return 0;
    }
    
    char full_path[128];
    snprintf(full_path, sizeof(full_path), "%s%s", TASK_COMM_DIR, filename);
    
    uint32_t bytes_read = 0;
    bool result = sd_read_file(full_path, buffer, buffer_size, &bytes_read);
    
    if (!result) {
        g_last_error = TASK_ERROR_LOAD_FAILED;
        return 0;
    }
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Loaded %u bytes from %s\n", bytes_read, full_path);
    }
    
    return bytes_read;
}

bool task_child_has_file(const char* filename) {
    if (!filename) return false;
    
    if (!sd_card_available()) {
        return false;
    }
    
    char full_path[128];
    snprintf(full_path, sizeof(full_path), "%s%s", TASK_COMM_DIR, filename);
    
    return sd_file_exists(full_path);
}

bool task_switcher_cleanup_frozen(void) {
    if (!g_parent_task.valid || !g_parent_task.freeze_file[0]) {
        g_last_error = TASK_ERROR_NO_FROZEN_TASK;
        return false;
    }
    
    if (!sd_card_available()) {
        g_last_error = TASK_ERROR_NO_SDCARD;
        return false;
    }
    
    bool result = sd_delete_file(g_parent_task.freeze_file);
    if (result && g_config.debug) {
        printf("[TASK_SWITCHER] Cleaned up frozen file: %s\n", g_parent_task.freeze_file);
    }
    
    if (result) {
        memset(&g_parent_task, 0, sizeof(g_parent_task));
        g_is_switched = false;
        g_state = TASK_STATE_NORMAL;
    } else {
        g_last_error = TASK_ERROR_RESTORE_FAILED;
    }
    
    return result;
}

// ============================================================================
// TASK INFORMATION
// ============================================================================

bool task_has_frozen_parent(void) {
    return g_is_switched && g_parent_task.valid;
}

bool task_get_frozen_parent(TaskInfo* info) {
    if (!info) return false;
    
    if (g_is_switched && g_parent_task.valid) {
        *info = g_parent_task;
        return true;
    }
    return false;
}

void task_get_current(TaskInfo* info) {
    if (info) {
        *info = g_current_task;
    }
}

// ============================================================================
// CORE SWITCHING FUNCTIONS
// ============================================================================

/**
 * @brief Freeze current task RAM to SD card
 */
static bool freeze_current_task(const char* freeze_file) {
    if (!sd_card_available()) {
        g_last_error = TASK_ERROR_NO_SDCARD;
        return false;
    }
    
    // Get RAM info
    uint32_t ram_start = 0;
    uint32_t ram_size = get_total_ram();
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Freezing %u bytes from 0x%08X to %s\n", 
               ram_size, ram_start, freeze_file);
    }
    
    // Use the RAM freeze system to save current state
    bool result = ram_freeze_to_file(freeze_file, (void*)ram_start, ram_size);
    
    if (!result) {
        g_last_error = TASK_ERROR_FREEZE_FAILED;
        printf("[TASK_SWITCHER] ERROR: Failed to freeze RAM\n");
        return false;
    }
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Successfully froze RAM to %s\n", freeze_file);
    }
    
    return true;
}

/**
 * @brief Thaw parent task RAM from SD card
 */
static bool thaw_parent_task(const char* freeze_file) {
    if (!sd_card_available()) {
        g_last_error = TASK_ERROR_NO_SDCARD;
        return false;
    }
    
    // Get RAM info
    uint32_t ram_start = 0;
    uint32_t ram_size = get_total_ram();
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Thawing %u bytes to 0x%08X from %s\n", 
               ram_size, ram_start, freeze_file);
    }
    
    // Use the RAM freeze system to restore state
    bool result = ram_thaw_from_file(freeze_file, (void*)ram_start, ram_size);
    
    if (!result) {
        g_last_error = TASK_ERROR_RESTORE_FAILED;
        printf("[TASK_SWITCHER] ERROR: Failed to thaw RAM\n");
        return false;
    }
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Successfully thawed RAM from %s\n", freeze_file);
    }
    
    return true;
}

/**
 * @brief Load kernel from SD card and jump to it
 * 
 * @note This is a simplified version. In real implementation, this would:
 *       1. Read kernel file from SD
 *       2. Verify checksum
 *       3. Jump to kernel entry point
 */
static bool load_and_jump_to_kernel(const char* kernel_path) {
    (void)kernel_path;
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Loading kernel: %s\n", kernel_path);
        printf("[TASK_SWITCHER] Jumping to new task...\n");
    }
    
    // In real implementation:
    // 1. Read kernel from SD card
    // 2. Copy to RAM
    // 3. Jump to entry point
    //
    // For demo purposes, we'll simulate this by updating state
    // In a real system, this function would not return
    
    strncpy(g_current_task.kernel_path, kernel_path, sizeof(g_current_task.kernel_path));
    g_current_task.valid = true;
    
    // Simulate successful load
    return true;
}

bool task_switch_to(const char* new_kernel_path) {
    if (!new_kernel_path || !new_kernel_path[0]) {
        g_last_error = TASK_ERROR_LOAD_FAILED;
        return false;
    }
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] === TASK SWITCH START ===\n");
        printf("[TASK_SWITCHER] Current task: %s\n", g_current_task.kernel_path);
        printf("[TASK_SWITCHER] New task: %s\n", new_kernel_path);
    }
    
    // Check SD card
    if (!sd_card_available()) {
        g_last_error = TASK_ERROR_NO_SDCARD;
        printf("[TASK_SWITCHER] ERROR: SD card not available\n");
        g_state = TASK_STATE_ERROR;
        return false;
    }
    
    // Check free RAM
    if (!task_switcher_has_enough_ram(g_config.min_free_ram)) {
        g_last_error = TASK_ERROR_INSUFFICIENT_RAM;
        printf("[TASK_SWITCHER] ERROR: Insufficient free RAM (need %u%%)\n", 
               g_config.min_free_ram);
        g_state = TASK_STATE_ERROR;
        return false;
    }
    
    // Save parent task info
    g_parent_task = g_current_task;
    strncpy(g_parent_task.freeze_file, g_config.frozen_task_file, 
            sizeof(g_parent_task.freeze_file));
    g_parent_task.valid = true;
    
    // Freeze current task to SD card
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Freezing current task...\n");
    }
    
    if (!freeze_current_task(g_config.frozen_task_file)) {
        g_state = TASK_STATE_ERROR;
        return false;
    }
    
    // Load and jump to new task
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Loading new task...\n");
    }
    
    g_is_switched = true;
    g_state = TASK_STATE_FROZEN;
    
    // Update current task info
    strncpy(g_current_task.kernel_path, new_kernel_path, 
            sizeof(g_current_task.kernel_path));
    
    // Load the new kernel
    bool result = load_and_jump_to_kernel(new_kernel_path);
    
    if (!result) {
        g_last_error = TASK_ERROR_LOAD_FAILED;
        g_state = TASK_STATE_ERROR;
        return false;
    }
    
    // In real implementation, we would jump to the new task and never return
    // For demo/testing purposes, we return true
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Successfully switched to: %s\n", new_kernel_path);
    }
    
    return true;
}

bool task_restore(void) {
    if (g_config.debug) {
        printf("[TASK_SWITCHER] === TASK RESTORE START ===\n");
    }
    
    // Check if we have a frozen parent
    if (!task_has_frozen_parent()) {
        g_last_error = TASK_ERROR_NO_FROZEN_TASK;
        printf("[TASK_SWITCHER] ERROR: No frozen parent task to restore\n");
        g_state = TASK_STATE_ERROR;
        return false;
    }
    
    // Check SD card
    if (!sd_card_available()) {
        g_last_error = TASK_ERROR_NO_SDCARD;
        printf("[TASK_SWITCHER] ERROR: SD card not available\n");
        g_state = TASK_STATE_ERROR;
        return false;
    }
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Restoring parent task from: %s\n", 
               g_parent_task.freeze_file);
    }
    
    // Thaw parent task from SD card
    if (!thaw_parent_task(g_parent_task.freeze_file)) {
        g_state = TASK_STATE_ERROR;
        return false;
    }
    
    // Clean up frozen file if configured
    if (g_config.auto_cleanup) {
        task_switcher_cleanup_frozen();
    }
    
    // Update state
    g_current_task = g_parent_task;
    memset(&g_parent_task, 0, sizeof(g_parent_task));
    g_is_switched = false;
    g_state = TASK_STATE_NORMAL;
    
    if (g_config.debug) {
        printf("[TASK_SWITCHER] Successfully restored parent task: %s\n", 
               g_current_task.kernel_path);
        printf("[TASK_SWITCHER] === TASK RESTORE COMPLETE ===\n");
    }
    
    // In real implementation, we would resume execution of the parent task
    // For demo purposes, we return true
    
    return true;
}
